import{_ as a}from"./chunks/site-models.D4MLFUg0.js";import{_ as t}from"./chunks/tray-panel.kylWqXfw.js";import{_ as s,o as r,c as i,a3 as o}from"./chunks/framework.BTt0kA_k.js";const l="/RelayPulse/screenshots/user/site-add.webp",b=JSON.parse('{"title":"完成第一次探测","description":"","frontmatter":{},"headers":[],"relativePath":"user/start/quick-start.md","filePath":"user/start/quick-start.md"}'),p={name:"user/start/quick-start.md"};function c(n,e,d,h,u,f){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="完成第一次探测" tabindex="-1">完成第一次探测 <a class="header-anchor" href="#完成第一次探测" aria-label="Permalink to &quot;完成第一次探测&quot;">​</a></h1><p>目标是添加一个站点、启用一个模型，并在小面板和探测记录里找到结果。</p><h2 id="_1-准备连接信息" tabindex="-1">1. 准备连接信息 <a class="header-anchor" href="#_1-准备连接信息" aria-label="Permalink to &quot;1. 准备连接信息&quot;">​</a></h2><p>从模型服务商处确认三个信息：<strong>接口协议、服务地址、API Key</strong>。优先使用服务商明确支持的协议。</p><p>新建站点默认从 <code>/v1/models</code> 获取模型列表，并按协议使用默认探测端点。因此，服务地址不带路径时，先填写类似 <code>https://api.example.com</code> 的 Base URL。</p><div class="tip custom-block"><p class="custom-block-title">留意地址中的路径</p><p>程序会把端点追加到 Base URL 后面，并保留 Base URL 原有的路径。<code>https://api.example.com/v1</code> 加 <code>/v1/models</code> 会得到 <code>/v1/v1/models</code>。有网关前缀或特殊路径时，先看<a href="./../use/sites.html#base-url-与端点怎样填写">地址拼接说明</a>。</p></div><h2 id="_2-添加站点" tabindex="-1">2. 添加站点 <a class="header-anchor" href="#_2-添加站点" aria-label="Permalink to &quot;2. 添加站点&quot;">​</a></h2><ol><li>打开“配置 → 站点管理”。</li><li>点击“添加第一个站点”；已有站点时，点击左侧站点列表上方的加号。</li><li>填写站点名称、接口协议、Base URL 和 API Key。</li><li>保留“在小面板中显示”勾选。</li><li>点击“连接并获取模型”，等待站点创建和模型列表读取完成。</li></ol><p>成功后，左侧会出现新站点，右侧显示基本信息、默认探针策略和模型列表。连接失败时，检查错误提示和连接信息；当前创建流程需要模型列表读取成功后才会保存站点。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/site-add.webp"><img src="'+l+'" alt="添加站点窗口，填写名称、协议、Base URL 和访问凭据后连接并获取模型"></a></p><figcaption>① 名称与协议；② 服务地址与 API Key；③ 连接并获取模型。图中的本地地址用于演示，请填写服务商提供的实际地址。点击图片可查看大图。</figcaption></figure><h2 id="_3-选择要探测的模型" tabindex="-1">3. 选择要探测的模型 <a class="header-anchor" href="#_3-选择要探测的模型" aria-label="Permalink to &quot;3. 选择要探测的模型&quot;">​</a></h2><p>在模型列表中找到需要监测的模型，打开该模型的探测开关。第一次使用先选择一个，确认成功后再增加。</p><p>模型不在列表中时，可以点击“添加模型”并输入服务商提供的完整模型标识。能手动添加并不代表该模型一定能被当前 API Key 调用，仍需通过探测验证。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/site-models.webp"><img src="'+a+'" alt="站点的模型列表及探测开关、探测和同步按钮"></a></p><figcaption>① 探测、同步与添加模型；② 各模型的探测开关、策略和操作入口。图中三个模型用于展示不同结果。</figcaption></figure><h2 id="_4-发起正式探测" tabindex="-1">4. 发起正式探测 <a class="header-anchor" href="#_4-发起正式探测" aria-label="Permalink to &quot;4. 发起正式探测&quot;">​</a></h2><p>点击模型行的“立即探测模型”图标。若要探测当前站点所有已启用模型，点击“探测已启用模型”。</p><p>等待请求结束，然后前往“运行 → 探测记录”，查看对应模型的最新一条记录。这里可以确认本次请求是成功、偏慢还是失败，以及实际耗时。</p><p>若出现失败，打开记录详情，检查 HTTP 状态、错误提示、请求端点和原始返回；排查路径见<a href="./../faq.html">常见问题</a>。</p><h2 id="_5-在状态栏查看结果" tabindex="-1">5. 在状态栏查看结果 <a class="header-anchor" href="#_5-在状态栏查看结果" aria-label="Permalink to &quot;5. 在状态栏查看结果&quot;">​</a></h2><p>点击 macOS 状态栏中的 RelayPulse 图标打开小面板，查看模型状态和“首 Token / 总耗时”。</p><ul><li>“正常”：模型已达到健康判定要求，本次有效结果未达到慢阈值。</li><li>“偏慢”：请求成功，但首 Token 或总耗时达到设置的慢阈值。</li><li>“待确认”：已有结果，尚未达到稳定健康状态的判定阈值。</li><li>“不可用”：连续失败已达到转红阈值。</li></ul><p><strong>一次请求失败和模型被判定为不可用是两件事。</strong></p><p>本次结果在记录里查看；稳定状态在小面板查看，具体规则见<a href="./../use/probes.html#健康状态怎样判定">状态判定</a>。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/tray-panel.webp"><img src="'+t+'" alt="托盘小面板展示正常、偏慢和不可用三个模型以及首 Token 和总耗时"></a></p><figcaption>① 正常；② 偏慢；③ 不可用。每行右侧依次显示首 Token 与总耗时。本例为便于演示已暂停周期探测，开启方式见下一步。</figcaption></figure><h2 id="_6-保持周期探测" tabindex="-1">6. 保持周期探测 <a class="header-anchor" href="#_6-保持周期探测" aria-label="Permalink to &quot;6. 保持周期探测&quot;">​</a></h2><p>在“配置 → 通用设置”保持“关闭主窗口后继续运行”开启，同时保持站点和模型启用。自动探测默认间隔为 <strong>300 秒</strong>，可在站点“高级设置”中调整。</p><p>小面板底部显示下次探测时间，说明周期探测已安排；显示“未启用周期探测”时，按<a href="./../faq.html#为什么没有自动探测">自动探测排查</a>检查。</p>',27)])])}const P=s(p,[["render",c]]);export{b as __pageData,P as default};
